using Microsoft.EntityFrameworkCore;using ProMaxx2.QA.Application.TestManagement;using ProMaxx2.QA.Domain.TestManagement;using ProMaxx2.QA.Application.Common;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class TestCaseRepository(QaDbContext db,ProjectAccessContext projectCtx):ITestCaseRepository
{
 public async Task<PagedResult<TestCaseListDto>>ListAsync(Guid?projectId,Guid?moduleId,string?priority,string?testType,string?status,bool? automation,string?search,string?automationTarget,Guid?createdBy,string?sortBy,int page,int size,CancellationToken ct){var q=db.TestCases.AsNoTracking().Where(x=>!x.IsDeleted);if(projectId.HasValue)q=q.Where(x=>x.ProjectId==projectId);else if(projectCtx.AllowedProjectIds.Length>0)q=q.Where(x=>projectCtx.AllowedProjectIds.Contains(x.ProjectId));else q=q.Where(_=>false);if(moduleId.HasValue)q=q.Where(x=>x.ModuleId==moduleId);if(!string.IsNullOrWhiteSpace(priority))q=q.Where(x=>x.Priority==priority);if(!string.IsNullOrWhiteSpace(testType))q=q.Where(x=>x.TestType==testType);if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(automation.HasValue)q=q.Where(x=>x.AutomationCandidate==automation);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.TestCaseCode.Contains(search)||x.Title.Contains(search));if(!string.IsNullOrWhiteSpace(automationTarget))q=automationTarget=="unset"?q.Where(x=>x.AutomationTarget==null):q.Where(x=>x.AutomationTarget==automationTarget);if(createdBy.HasValue)q=q.Where(x=>x.CreatedBy==createdBy);var total=await q.CountAsync(ct);var p=Math.Max(1,page);var s=Math.Clamp(size,20,100);var ordered=sortBy=="priority"?q.OrderBy(x=>x.Priority).ThenByDescending(x=>x.CreatedAt):sortBy=="status"?q.OrderBy(x=>x.Status).ThenByDescending(x=>x.CreatedAt):q.OrderByDescending(x=>x.CreatedAt);var items=await ordered.Skip((p-1)*s).Take(s).Select(x=>new TestCaseListDto(x.TestCaseId,x.ProjectId,x.ModuleId,x.TestCaseCode,x.Title,x.Priority,x.TestType,x.AutomationCandidate,x.Status,x.RevisionNo,x.OwnerUserId,x.Steps.Count(s=>s.RevisionNo==x.RevisionNo),x.AutomationTarget,x.CreatedBy,db.Users.Where(u=>u.UserId==x.CreatedBy).Select(u=>u.DisplayName).FirstOrDefault(),x.CreatedAt)).ToListAsync(ct);return new(total,items);}
 public async Task<AutomationCandidateSummaryDto>AutomationSummaryAsync(Guid projectId,CancellationToken ct){var q=db.TestCases.AsNoTracking().Where(x=>!x.IsDeleted&&x.ProjectId==projectId&&x.AutomationCandidate);var total=await q.CountAsync(ct);var ready=await q.CountAsync(x=>x.Status=="Ready");var pos=await q.CountAsync(x=>x.AutomationTarget=="pos");var app=await q.CountAsync(x=>x.AutomationTarget=="app");return new(total,ready,pos,app,total-pos-app);}
 public async Task<TestCaseDto?>GetAsync(Guid id,CancellationToken ct){var allowed=projectCtx.AllowedProjectIds;var q=db.TestCases.AsNoTracking().Where(x=>x.TestCaseId==id&&!x.IsDeleted);if(allowed.Length>0)q=q.Where(x=>allowed.Contains(x.ProjectId));return await q.Select(x=>new TestCaseDto(x.TestCaseId,x.ProjectId,x.ModuleId,x.TestCaseCode,x.Title,x.Objective,x.Preconditions,x.Priority,x.TestType,x.AutomationCandidate,x.Status,x.RevisionNo,x.OwnerUserId,x.Steps.Where(s=>s.RevisionNo==x.RevisionNo).OrderBy(s=>s.StepNo).Select(s=>new StepDto(s.StepNo,s.Action,s.TestDataText,s.ExpectedResult)).ToList(),x.AutomationTarget)).SingleOrDefaultAsync(ct);}public async Task<TestCase?>FindAsync(Guid id,CancellationToken ct){var allowed=projectCtx.AllowedProjectIds;var e=await db.TestCases.Include(x=>x.Steps).SingleOrDefaultAsync(x=>x.TestCaseId==id&&!x.IsDeleted,ct);if(e is not null&&allowed.Length>0&&!allowed.Contains(e.ProjectId))return null;return e;}public Task<bool>CodeExistsAsync(Guid projectId,string code,CancellationToken ct)=>db.TestCases.AnyAsync(x=>x.ProjectId==projectId&&x.TestCaseCode==code,ct);public Task AddAsync(TestCase e,CancellationToken ct)=>db.TestCases.AddAsync(e,ct).AsTask();public void AddSteps(IEnumerable<TestStep>steps)=>db.TestSteps.AddRange(steps);
 public async Task LinkAsync(Guid reqId,Guid caseId,string?type,CancellationToken ct){if(!await db.Requirements.AnyAsync(x=>x.RequirementId==reqId&&!x.IsDeleted,ct)||!await db.TestCases.AnyAsync(x=>x.TestCaseId==caseId&&!x.IsDeleted,ct))throw new ProMaxx2.QA.Application.Projects.EntityNotFoundException("Requirement or test case not found.");if(!await db.RequirementTestCases.AnyAsync(x=>x.RequirementId==reqId&&x.TestCaseId==caseId,ct))await db.RequirementTestCases.AddAsync(new(reqId,caseId,type),ct);}public async Task UnlinkAsync(Guid reqId,Guid caseId,CancellationToken ct){var link=await db.RequirementTestCases.FindAsync([reqId,caseId],ct);if(link is not null)db.RequirementTestCases.Remove(link);}
 public async Task<IReadOnlyList<string>>ListCodesAsync(Guid projectId,string prefix,CancellationToken ct)=>await db.TestCases.AsNoTracking().Where(x=>x.ProjectId==projectId&&x.TestCaseCode.StartsWith(prefix)).Select(x=>x.TestCaseCode).ToListAsync(ct);
 public async Task<RtmListResultDto>RtmAsync(Guid releaseId,string?search,string?moduleId,string?coverage,string?status,int page,int size,CancellationToken ct){var requirements=await db.Requirements.AsNoTracking().Where(x=>x.ReleaseId==releaseId&&x.IsInScope&&!x.IsDeleted).OrderBy(x=>x.RequirementCode).Select(x=>new{x.RequirementId,x.ModuleId,ModuleName=x.ModuleId.ToString(),x.RequirementCode,x.Title,x.Priority,x.Status}).ToListAsync(ct);if(!string.IsNullOrWhiteSpace(moduleId)&&Guid.TryParse(moduleId,out var mid))requirements=requirements.Where(x=>x.ModuleId==mid).ToList();if(!string.IsNullOrWhiteSpace(search))requirements=requirements.Where(x=>x.RequirementCode.Contains(search)||x.Title.Contains(search)).ToList();if(!string.IsNullOrWhiteSpace(status))requirements=requirements.Where(x=>x.Status==status).ToList();var moduleIds=requirements.Select(x=>x.ModuleId).Distinct().ToArray();var moduleNames=await db.Modules.AsNoTracking().Where(x=>moduleIds.Contains(x.ModuleId)).ToDictionaryAsync(x=>x.ModuleId,x=>x.ModuleName,ct);var requirementIds=requirements.Select(x=>x.RequirementId).ToArray();var links=await db.RequirementTestCases.AsNoTracking().Where(x=>requirementIds.Contains(x.RequirementId)).Join(db.TestCases.AsNoTracking().Where(x=>!x.IsDeleted),l=>l.TestCaseId,t=>t.TestCaseId,(l,t)=>new{l.RequirementId,l.CoverageType,t.TestCaseId,t.TestCaseCode,t.Title,t.Priority,t.TestType,t.Status,t.RevisionNo}).ToListAsync(ct);var rows=requirements.Select(r=>{var cases=links.Where(x=>x.RequirementId==r.RequirementId).Select(x=>new RtmLinkedTestCase(x.TestCaseId,x.TestCaseCode,x.Title,x.Priority,x.TestType,x.Status,x.RevisionNo,x.CoverageType)).ToList();var cov=cases.Count==0?"Not Covered":cases.Any(x=>x.Status=="Ready")?"Covered":"Partial";return new RtmRow(r.RequirementId,r.ModuleId,moduleNames.GetValueOrDefault(r.ModuleId,"-"),r.RequirementCode,r.Title,r.Priority,cases.Count,cov,r.Status,cases);}).ToList();if(!string.IsNullOrWhiteSpace(coverage))rows=rows.Where(x=>x.CoverageStatus.Equals(coverage,StringComparison.OrdinalIgnoreCase)).ToList();var total=rows.Count;var p=Math.Max(1,page);var s=Math.Clamp(size,20,100);var paged=rows.Skip((p-1)*s).Take(s).ToList();var coveredCount=rows.Count(x=>x.CoverageStatus=="Covered");var partialCount=rows.Count(x=>x.CoverageStatus=="Partial");var notCoveredCount=rows.Count(x=>x.CoverageStatus=="Not Covered");var statuses=rows.Select(x=>x.Status).Distinct().OrderBy(x=>x).ToList();return new(new(total,paged),new(coveredCount,partialCount,notCoveredCount,statuses));}
 public async Task<CoverageSummary>CoverageAsync(Guid releaseId,CancellationToken ct){var result=await RtmAsync(releaseId,null,null,null,null,1,int.MaxValue,ct);var rows=result.Items.Rows;var covered=rows.Count(x=>x.CoverageStatus=="Covered");var notCovered=rows.Count(x=>x.CoverageStatus=="Not Covered");var pct=rows.Count==0?0:Math.Round((decimal)covered/rows.Count*100,1);return new(rows.Count,covered,notCovered,pct);}
 public async Task<IReadOnlyList<TestCaseRevisionDto>>RevisionsAsync(Guid id,CancellationToken ct){var revisions=await db.TestCaseRevisions.AsNoTracking().Where(x=>x.TestCaseId==id).OrderByDescending(x=>x.RevisionNo).Select(x=>new{x.RevisionNo,x.ChangeReason,x.ChangedBy,x.ChangedAt,ChangedByName=x.ChangedBy==null?null:db.Users.Where(u=>u.UserId==x.ChangedBy).Select(u=>u.DisplayName).FirstOrDefault()}).ToListAsync(ct);var steps=await db.TestSteps.AsNoTracking().Where(x=>x.TestCaseId==id).OrderBy(x=>x.StepNo).Select(x=>new{x.RevisionNo,Step=new StepDto(x.StepNo,x.Action,x.TestDataText,x.ExpectedResult)}).ToListAsync(ct);return revisions.Select(x=>new TestCaseRevisionDto(x.RevisionNo,x.ChangeReason,x.ChangedBy,x.ChangedByName,x.ChangedAt,steps.Where(s=>s.RevisionNo==x.RevisionNo).Select(s=>s.Step).ToList())).ToList();}
 public async Task<IReadOnlyList<TestCaseRequirementDto>>RequirementsAsync(Guid id,CancellationToken ct)=>await db.RequirementTestCases.AsNoTracking().Where(x=>x.TestCaseId==id).Join(db.Requirements.AsNoTracking().Where(x=>!x.IsDeleted),l=>l.RequirementId,r=>r.RequirementId,(l,r)=>new TestCaseRequirementDto(r.RequirementId,r.RequirementCode,r.Title,r.Status,l.CoverageType)).OrderBy(x=>x.RequirementCode).ToListAsync(ct);
 public Task SaveAsync(CancellationToken ct)=>db.SaveChangesAsync(ct);
}
